import type{MedusaRequest,MedusaResponse}from'@medusajs/framework/http';import{ContainerRegistrationKeys}from'@medusajs/framework/utils';const aid=(r:any)=>r.auth_context?.actor_id||r.auth_context?.auth_identity_id;async function sid(req:any,a:string){const q=req.scope.resolve(ContainerRegistrationKeys.QUERY)as any;const{data}=await q.graph({entity:'seller_member',fields:['seller.id'],filters:{member_id:a},pagination:{take:1}}).catch(()=>({data:[]}));return data?.[0]?.seller?.id}export async function GET(req:MedusaRequest,res:MedusaResponse){const s=await sid(req,aid(req));if(!s)return res.status(403).json({message:'Seller not found'});const sp=req.scope.resolve('spike')as any;res.json({returns:await sp.listSpikeReturnRequests({seller_id:s},{take:500,order:{created_at:'DESC'}})})}
